import { writable, get, derived } from 'svelte/store';
import {
	createGame,
	createSudoku,
	cloneGame,
	isValidGamePosition,
	canApplyGameHint,
	guessGame,
	undoGame,
	redoGame,
	canUndoGame,
	canRedoGame,
	isGameWon,
	projectGame,
} from '../../domain/index.js';
import { generateSudoku, solveSudoku } from '@sudoku/sudoku';
import { decodeSencode, encodeSudoku } from '@sudoku/sencode';
import { hints } from './stores/hints';

function createEmptyGrid() {
	const emptyGrid = Array.from({ length: 9 }, () => Array(9).fill(0));
	return emptyGrid;
}

function createEmptyGame() {
	return createGame({ sudoku: createSudoku(createEmptyGrid()) });
}

function isValidPosition(pos) {
	return isValidGamePosition(pos);
}

function createGameStore() {
	const { subscribe, set, update } = writable(createEmptyGame());

	function mutateGame(mutator) {
		update(game => {
			if (!game) {
				return game;
			}

			const nextGame = cloneGame(game);
			const changed = mutator(nextGame, game);

			return changed === false ? game : nextGame;
		});
	}

	return {
		subscribe,

		
		startNew(difficulty) {
			const grid = generateSudoku(difficulty);
			set(createGame({ sudoku: createSudoku(grid) }));
		},

		startCustom(sencode) {
			const grid = decodeSencode(sencode);
			set(createGame({ sudoku: createSudoku(grid) }));
		},

		startCreatorMode() {
			set(createEmptyGame());
		},

		get(pos) {
			const game = get(this);
			if (!game || !isValidPosition(pos)) return 0;
			return projectGame(game).grid[pos.y][pos.x];
		},

		getView() {
			return projectGame(get(this));
		},

		isEditable(pos) {
			return projectGame(get(this)).editableGrid[pos.y]?.[pos.x] ?? false;
		},

		canHint(pos) {
			return canApplyGameHint(get(this), pos);
		},

		getSencode() {
			const game = get(this);
			if (!game) return '';
			return encodeSudoku(projectGame(game).grid);
		},

		set(pos, value) {
			if (!isValidPosition(pos)) {
				return;
			}

			mutateGame(game => guessGame(game, { row: pos.y, col: pos.x, value }));
		},

		applyHint(pos) {
			mutateGame(game => {
				if (!canApplyGameHint(game, pos)) {
					return false;
				}

				const solved = solveSudoku(projectGame(game).grid);
				const hintedValue = solved?.[pos.y]?.[pos.x];

				if (!hintedValue) {
					return false;
				}

				const applied = guessGame(game, {
					row: pos.y,
					col: pos.x,
					value: hintedValue
				});

				if (!applied) {
					return false;
				}

				hints.useHint();
				return true;
			});
		},

		
		undo() {
			mutateGame(game => {
				if (!canUndoGame(game)) {
					return false;
				}

				undoGame(game);
				return true;
			});
		},

		redo() {
			mutateGame(game => {
				if (!canRedoGame(game)) {
					return false;
				}

				redoGame(game);
				return true;
			});
		},

	
		getGrid() {
			return projectGame(get(this)).grid;
		},

		canUndo() {
			return projectGame(get(this)).canUndo;
		},

		canRedo() {
			return projectGame(get(this)).canRedo;
		},

		isWon() {
			return projectGame(get(this)).isWon;
		}
	};
}

export const gameStore = createGameStore();
export const gameView = derived(gameStore, ($gameStore) => projectGame($gameStore));
export const gamePaused = writable(false);
export const gameWon = derived(
	gameView,
	($gameView) => $gameView.isWon,
    false
);